from collections import defaultdict
from typing import List

class Solution:
    def numberOfComponents(self, properties: List[List[int]], k: int) -> int:
        n = len(properties)
        m = len(properties[0]) if n > 0 else 0

        # Build adjacency list
        adj = [[] for _ in range(n)]

        # Calculate intersection for each pair and build edges
        for i in range(n):
            for j in range(i + 1, n):
                intersect = 0
                for x in properties[i]:
                    for y in properties[j]:
                        if x == y:
                            intersect += 1
                if intersect >= k:
                    adj[i].append(j)
                    adj[j].append(i)

        # Count connected components using BFS/DFS
        visited = [False] * n
        components = 0

        def dfs(node):
            visited[node] = True
            for neighbor in adj[node]:
                if not visited[neighbor]:
                    components += 1
                    dfs(neighbor)

        # Start BFS from all unvisited nodes
        for i in range(n):
            if not visited[i]:
                components += 1
                dfs(i)

        return components
